package aurora

// Workflow returns the canonical, model-facing brief for an available expert.
// Availability is decided by the same execution policy that gates a task, so an
// unknown skill can never receive a brief. The returned string is a copy the
// caller owns.
//
// The briefs are the vendored expert workflows (experts_assets.go): one file per
// expert under server/internal/aurora/experts/<slug>/workflow.md, generated by
// scripts/aurora-import-experts.mjs.
func Workflow(skillID string) (string, bool) {
	if _, ok := ExecutionPolicy(skillID); !ok {
		return "", false
	}
	return ExpertWorkflow(skillID)
}
